// Arrow-key navigation — active only while the lightbox is mounted
useEffect(() => {
  function onKeyDown(e: KeyboardEvent) {
    // Do not interfere with textarea / input inside the lightbox (caption editor)
    const target = e.target as HTMLElement
    if (target.tagName === 'INPUT' || target.tagName === 'TEXTAREA' || target.isContentEditable) return
    // Do not swallow Esc — Radix Dialog handles it
    if (e.key === 'ArrowLeft') {
      e.preventDefault()
      setIdx((i) => (i === 0 ? state.photos.length - 1 : i - 1))
    } else if (e.key === 'ArrowRight') {
      e.preventDefault()
      setIdx((i) => (i === state.photos.length - 1 ? 0 : i + 1))
    }
  }

  window.addEventListener('keydown', onKeyDown)
  return () => window.removeEventListener('keydown', onKeyDown)
}, [state.photos.length])

const photo = state.photos[idx] as PhotoWithPrivacy | undefined
